// Calculate angle between two points relative to origin
double getAngle(Point p) {
    return atan2(p.y, p.x) * 180.0 / M_PI;
}

// Normalize angle to [0, 360)
double normalizeAngle(double angle) {
    while(angle < 0) angle += 360;
    while(angle >= 360) angle -= 360;
    return angle;
}

// Check if a point is within the wind's fan
bool isInFan(Point p, Wind w) {
    double angle = getAngle(p);
    double dist = sqrt(p.x * p.x + p.y * p.y);

    // If at origin, it's always within fan
    if(dist == 0) return true;

    // Fan angle is proportional to wind strength
    double fanHalfAngle = w.strength * 1.8; // Max 180 degrees at strength 100

    double windAngle = w.dir;
    double diff = abs(normalizeAngle(angle - windAngle));
    diff = min(diff, 360 - diff);

    return diff <= fanHalfAngle;
}

// Check if scent from a tree reaches a house
bool scentReaches(Point tree, Point house, Wind w) {
    // The scent from tree spreads in a fan from the tree's position
    // We need to check if house is within the fan originating from the tree

    Point relativeToTree = {house.x - tree.x, house.y - tree.y};
    return isInFan(relativeToTree, w);
}

