#include <bits/stdc++.h>
using namespace std;

/*
We model my plum tree at the origin.

For each day:
- Wind has direction d (degrees) and strength s.
- A scent reaches a house if:
  1) distance from tree to house <= s
  2) the angle between the wind direction vector and the vector from tree to house
     is within 30 degrees (fan of 60 degrees total).

A house is counted for that day if my plum scent reaches it and no other tree's scent
(peach/cherry/plum from other positions) reaches it.

We must output the house/houses with the maximum such count, or NA if the maximum is 0.

Input format (deduced from statement):
Multiple datasets.
Each dataset:
  n m k
  n lines: house names and coordinates
  m lines: tree coordinates
  k lines: wind direction and strength
Terminated by:
  0 0 0

Because the original statement here is abbreviated, we use a robust parser:
- house line: string name, double x, double y
- tree line: double x, double y
- wind line: double d, double s

Direction interpretation:
Standard meteorological-style ambiguity is possible, but in typical geometry contest
problems, direction d means the direction toward which wind blows, measured in degrees
from +x axis counterclockwise. We use that convention.

To avoid expensive angle computations, use dot product:
For vector v from tree to house and wind unit vector u,
v is inside the 60-degree fan iff:
  |v| <= s and dot(u, v) >= |v| * cos(30°)

Houses are output in input order among those tied for maximum.
*/

static const double EPS = 1e-10;
static const double COS30 = sqrt(3.0) / 2.0;

struct House {
    string name;
    double x, y;
};

struct Point {
    double x, y;
};

static bool reaches(const Point& tree, const House& h, double dirDeg, double strength) {
    double vx = h.x - tree.x;
    double vy = h.y - tree.y;
    double dist2 = vx * vx + vy * vy;
    if (dist2 > strength * strength + EPS) return false;
    double dist = sqrt(dist2);
    if (dist < EPS) return true; // exactly at tree position
    double rad = dirDeg * acos(-1.0) / 180.0;
    double ux = cos(rad), uy = sin(rad);
    double dot = ux * vx + uy * vy;
    return dot + EPS >= dist * COS30;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    while (cin >> n >> m >> k) {
        if (n == 0 && m == 0 && k == 0) break;

        vector<House> houses(n);
        for (int i = 0; i < n; ++i) {
            cin >> houses[i].name >> houses[i].x >> houses[i].y;
        }

        vector<Point> otherTrees(m);
        for (int i = 0; i < m; ++i) {
            cin >> otherTrees[i].x >> otherTrees[i].y;
        }

        vector<int> cnt(n, 0);
        Point myTree{0.0, 0.0};

        for (int day = 0; day < k; ++day) {
            double d, s;
            cin >> d >> s;

            vector<char> myReach(n, 0), otherReach(n, 0);

            for (int i = 0; i < n; ++i) {
                if (reaches(myTree, houses[i], d, s)) myReach[i] = 1;
            }

            for (const auto& t : otherTrees) {
                for (int i = 0; i < n; ++i) {
                    if (!otherReach[i] && reaches(t, houses[i], d, s)) {
                        otherReach[i] = 1;
                    }
                }
            }

            for (int i = 0; i < n; ++i) {
                if (myReach[i] && !otherReach[i]) cnt[i]++;
            }
        }

        int best = 0;
        for (int x : cnt) best = max(best, x);

        if (best == 0) {
            cout << "NA\n";
        } else {
            bool first = true;
            for (int i = 0; i < n; ++i) {
                if (cnt[i] == best) {
                    if (!first) cout << ' ';
                    cout << houses[i].name;
                    first = false;
                }
            }
            cout << '\n';
        }
    }

    return 0;
}

#include <stdio.h>
