#define MAX_HOUSES 100
#define MAX_TREES 100
#define MAX_WIND 1000
#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

typedef struct {
    double angle, spread; // angle in radians, spread in radians
} Wind;

typedef struct {
    Point pos;
    int id;
} House;

int n_houses, n_trees, n_wind;
House houses[MAX_HOUSES];
Point trees[MAX_TREES];
Wind winds[MAX_WIND];
int best_count[MAX_HOUSES];

double normalize_angle(double a) {
    while (a < 0) a += 2 * M_PI;
    while (a >= 2 * M_PI) a -= 2 * M_PI;
    return a;
}

// Check if point is within the fan (angle ± spread/2)
int in_fan(Point p, Wind w) {
    double angle = atan2(p.y, p.x);
    angle = normalize_angle(angle);
    double center = normalize_angle(w.angle);
    double half = w.spread / 2.0;

    double diff = normalize_angle(angle - center);
    if (diff <= half + EPS || diff >= 2 * M_PI - half - EPS)
        return 1;
    return 0;
}

double dist2(Point a, Point b) {
    double dx = a.x - b.x, dy = a.y - b.y;
    return dx*dx + dy*dy;
}

int main() {
    int dataset = 0;
    while (1) {
        scanf("%d %d %d", &n_houses, &n_trees, &n_wind);
        if (n_houses == 0 && n_trees == 0 && n_wind == 0) break;
        dataset++;

        for (int i = 0; i < n_houses; i++) {
            scanf("%lf %lf", &houses[i].pos.x, &houses[i].pos.y);
            houses[i].id = i + 1;
            best_count[i] = 0;
        }

        for (int i = 0; i < n_trees; i++) {
            scanf("%lf %lf", &trees[i].x, &trees[i].y);
        }

        for (int i = 0; i < n_wind; i++) {
            double angle_deg, spread_deg;
            scanf("%lf %lf", &angle_deg, &spread_deg);
            winds[i].angle = angle_deg * M_PI / 180.0;
            winds[i].spread = spread_deg * M_PI / 180.0;
        }

        int max_days = 0;

        for (int d = 0; d < n_wind; d++) {
            Wind w = winds[d];

            // Count houses reached by plum scent this day
            int plum_houses[MAX_HOUSES];
            int n_plum = 0;

            for (int h = 0; h < n_houses; h++) {
                if (in_fan(houses[h].pos, w)) {
                    // Check if any other tree blocks or is closer
                    int blocked = 0;
                    double house_dist = dist2(houses[h].pos, (Point){0,0});

                    // Check other trees (peach and cherry)
                    for (int t = 0; t < n_trees; t++) {
                        double tree_dist = dist2(trees[t], (Point){0,0});
                        // If other tree is in the fan and closer than house, it blocks
                        if (in_fan(trees[t], w) && tree_dist < house_dist - EPS) {
                            blocked = 1;
                            break;
                        }
                    }

                    if (!blocked) {
                        plum_houses[n_plum++] = h;
                    }
                }
            }

            // For this day, only the houses that are reached are considered
            // We want days where ONLY plum scent reaches a house
            // So if more than one house is reached, that's still a day for those houses
            // But we need to check if any other tree's scent also reaches that house
            // Actually the problem says: "my plum tree's scent is the only one that reaches"
            // So we need to check if for a given house, only plum scent reaches it
            // That means: house is in plum fan, and no other tree is in the fan AND closer
            // But also other trees could be in the fan but farther - they still emit scent?
            // The problem says "scents spread in a fan shape" - if a tree is in the fan, its scent spreads
            // So if another tree is in the fan but farther, its scent also reaches the house? 
            // Actually scent spreads from each tree in its own fan. So if another tree is in the wind fan,
            // its scent also spreads. The house could receive multiple scents.
            // We need days where ONLY plum scent reaches the house.
            // That means: house is in plum fan, and for every other tree, either:
            // - the tree is not in the wind fan, OR
            // - the tree is in the wind fan but its scent doesn't reach the house 
            //   (because house is not in that tree's fan? No, all trees use same wind)
            // Actually all trees use the same wind data. So if a tree is in the wind fan,
            // its scent spreads in the same fan shape from its position.
            // So the house would receive scent from that tree if the vector from that tree to house
            // lies within the fan angle (from that tree's perspective).
            // But that's complex. Simpler interpretation: 
            // "my plum tree's scent is the only one that reaches" means that among all trees,
            // only the plum tree's scent reaches that house. Since all trees have the same wind,
            // a house is reached by a tree's scent if the house is within the tree's fan.
            // For the plum tree at origin, fan is from origin.
            // For other trees at positions T, fan is from T. So we need to check if house is
            // within fan from each other tree.

            // Actually let's re-read: "the scents of plum, peach, and cherry blossoms spread 
            // in a fan shape determined by direction and strength of the wind."
            // This means each tree's scent spreads with the same wind parameters but from its own position.
            // So for a house at H, it receives scent from tree at T if the vector H-T is within
            // the wind fan (same angle and spread as given).

            // So for each day, for each house, we need to check which trees' scents reach it.
            // A day counts for a house if only the plum tree's scent reaches it.

            // Let's redo properly:
            for (int h = 0; h < n_houses; h++) {
                Point house = houses[h].pos;

                // Check if plum reaches this house
                int plum_reaches = 0;
                if (in_fan(house, w)) {
                    plum_reaches = 1;
                }

                if (!plum_reaches) continue;

                // Check other trees
                int only_plum = 1;
                for (int t = 0; t < n_trees; t++) {
                    // Vector from tree to house
                    Point vec = {house.x - trees[t].x, house.y - trees[t].y};
                    // Check if this vector is within the wind fan
                    if (in_fan(vec, w)) {
                        only_plum = 0;
                        break;
                    }
                }

                if (only_plum) {
                    best_count[h]++;
                    if (best_count[h] > max_days)
                        max_days = best_count[h];
                }
            }
        }

        printf("Dataset %d:\n", dataset);
        if (max_days == 0) {
            printf("NA\n\n");
        } else {
            int first = 1;
            for (int h = 0; h < n_houses; h++) {
                if (best_count[h] == max_days) {
                    if (!first) printf(" ");
                    printf("%d", houses[h].id);
                    first = 0;
                }
            }
            printf("\n\n");
        }
    }
    return 0;
}

