        for (int i = 0; i < nh; i++) scanf("%lf %lf", &hx[i], &hy[i]);
        // My plum is at origin, tree[0] = (0,0)
        tx[0] = 0; ty[0] = 0;
        for (int i = 1; i <= nt; i++) scanf("%lf %lf", &tx[i], &ty[i]);
        // total trees = nt+1 (index 0 is mine)

        for (int w = 0; w < nw; w++) {
            double dir, str;
            scanf("%lf %lf", &dir, &str);
            double half = 45.0 / str * PI / 180.0;
            double wd = dir * PI / 180.0;
            double wvx = sin(wd), wvy = cos(wd);

            for (int h = 0; h < nh; h++) {
                int plum_reaches = 0, other_reaches = 0;
                for (int t = 0; t <= nt; t++) {
                    double vx = hx[h] - tx[t], vy = hy[h] - ty[t];
                    double len = sqrt(vx*vx + vy*vy);
                    if (len < 1e-9) { if(t==0) plum_reaches=1; continue; }
                    double cosA = (vx*wvx + vy*wvy)/len;
                    if (cosA >= cos(half) - 1e-9) {
                        if (t == 0) plum_reaches = 1;
                        else other_reaches = 1;
                    }
                }
                if (plum_reaches && !other_reaches) count[h]++;
            }
        }

        int mx = 0;
        for (int i = 0; i < nh; i++) if (count[i] > mx) mx = count[i];
        if (mx == 0) { printf("NA\n"); continue; }
        for (int i = 0; i < nh; i++) if (count[i] == mx) printf("%d\n", i+1);
    }
