#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

#define MAXN 205
#define MAXD 405
#define EPS 1e-10
#define PI acos(-1.0)

typedef struct {
    double x, y;
} Point;

typedef struct {
    double dir, str;
} Wind;

static Point houses[MAXN];
static Point peach[MAXN], cherry[MAXN];
static Wind winds[MAXD];

static double norm_angle(double a) {
    while (a < 0) a += 360.0;
    while (a >= 360.0) a -= 360.0;
    return a;
}

static double angle_deg(double x, double y) {
    double a = atan2(y, x) * 180.0 / PI;
    return norm_angle(a);
}

/*
Assumption used from the statement:
For a wind of direction dir and strength str, scent spreads in a fan
centered at dir with angular half-width 90/str.
A house receives scent from a tree if the direction from the tree to the
house lies inside that fan.

This matches the typical "fan shape determined by direction and strength".
*/
static int reaches(Point tree, Point house, Wind w) {
    double ang = angle_deg(house.x - tree.x, house.y - tree.y);
    double d = fabs(ang - norm_angle(w.dir));
    if (d > 180.0) d = 360.0 - d;
    double half = 90.0 / w.str;
    return d <= half + EPS;
}

int main(void) {
    int H, P, C, D;
    while (scanf("%d %d %d %d", &H, &P, &C, &D) == 4) {
        if (H == 0 && P == 0 && C == 0 && D == 0) break;

        for (int i = 0; i < H; i++) scanf("%lf %lf", &houses[i].x, &houses[i].y);
        for (int i = 0; i < P; i++) scanf("%lf %lf", &peach[i].x, &peach[i].y);
        for (int i = 0; i < C; i++) scanf("%lf %lf", &cherry[i].x, &cherry[i].y);
        for (int i = 0; i < D; i++) scanf("%lf %lf", &winds[i].dir, &winds[i].str);

        int best = 0;
        int ans[MAXN];
        int acnt = 0;

        Point plum = {0.0, 0.0};

        for (int i = 0; i < H; i++) {
            int cnt = 0;
            for (int d = 0; d < D; d++) {
                int plum_ok = reaches(plum, houses[i], winds[d]);
                if (!plum_ok) continue;

                int other = 0;
                for (int j = 0; j < P && !other; j++) {
                    if (reaches(peach[j], houses[i], winds[d])) other = 1;
                }
                for (int j = 0; j < C && !other; j++) {
                    if (reaches(cherry[j], houses[i], winds[d])) other = 1;
                }

                if (!other) cnt++;
            }

            if (cnt > best) {
                best = cnt;
                acnt = 0;
                ans[acnt++] = i + 1; /* 1-based house index */
            } else if (cnt == best && cnt > 0) {
                ans[acnt++] = i + 1;
            }
        }

        if (best == 0) {
            printf("NA\n");
        } else {
            for (int i = 0; i < acnt; i++) {
                if (i) printf(" ");
                printf("%d", ans[i]);
            }
            printf("\n");
        }
    }
    return 0;
}

