            for (int i = 0; i < T; i++) {
                trees[i][0] = sc.nextDouble();
                trees[i][1] = sc.nextDouble();
            }
            int D = sc.nextInt(); // number of days
            int[] windDir = new int[D];
            int[] windStr = new int[D];
            for (int i = 0; i < D; i++) {
                windDir[i] = sc.nextInt();
                windStr[i] = sc.nextInt();
            }
            int[] count = new int[H];
            for (int d = 0; d < D; d++) {
                double rad = Math.toRadians(windDir[d]);
                double dx = Math.sin(rad), dy = Math.cos(rad);
                for (int h = 0; h < H; h++) {
                    if (!inFan(0, 0, houses[h][0], houses[h][1], dx, dy, windStr[d])) continue;
                    boolean otherReaches = false;
                    for (int t = 0; t < T; t++) {
                        if (inFan(trees[t][0], trees[t][1], houses[h][0], houses[h][1], dx, dy, windStr[d])) {
                            otherReaches = true; break;
                        }
                    }
                    if (!otherReaches) count[h]++;
                }
            }
            int max = 0;
            for (int c : count) max = Math.max(max, c);
            if (max == 0) { System.out.println("NA"); continue; }
            StringBuilder sb = new StringBuilder();
            for (int h = 0; h < H; h++) if (count[h] == max) { if (sb.length()>0) sb.append(" "); sb.append(h+1); }
            System.out.println(sb.toString());
        }
    }
    static boolean inFan(double tx, double ty, double px, double py, double dx, double dy, int s) {
        double vx = px - tx, vy = py - ty;
        double dist = Math.sqrt(vx*vx + vy*vy);
        if (dist > s + 1e-9) return false;
        if (dist < 1e-9) return true;
        double cos = (vx*dx + vy*dy) / dist;
        return cos >= Math.cos(Math.toRadians(45));
    }
}

import java.util.*;

public class Main {
    static class Point {
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    static class House extends Point {
        int id;
        House(int id, int x, int y) { super(x, y); this.id = id; }
    }

    static class Tree extends Point {
        char type; // 'P' for peach, 'C' for cherry
        Tree(int x, int y, char type) { super(x, y); this.type = type; }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int dataset = 0;
        while (sc.hasNextInt()) {
            int N = sc.nextInt();
            if (N == 0) break;
            dataset++;
            List<House> houses = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                int x = sc.nextInt();
                int y = sc.nextInt();
                houses.add(new House(i + 1, x, y));
            }
            int M = sc.nextInt();
            List<Tree> trees = new ArrayList<>();
            for (int i = 0; i < M; i++) {
                int x = sc.nextInt();
                int y = sc.nextInt();
                char type = sc.next().charAt(0);
                trees.add(new Tree(x, y, type));
            }
            int K = sc.nextInt();
            int[] bestCount = new int[N];
            int maxCount = 0;
            for (int day = 0; day < K; day++) {
                int dirDeg = sc.nextInt();
                int strength = sc.nextInt();
                double dirRad = Math.toRadians(dirDeg);
                double halfAngle = Math.toRadians(90.0 / (strength + 1)); // strength controls narrowness

                // For each house, check if plum scent reaches
                boolean[] plumReach = new boolean[N];
                boolean[] peachReach = new boolean[N];
                boolean[] cherryReach = new boolean[N];

                for (int i = 0; i < N; i++) {
                    House h = houses.get(i);
                    double angleToHouse = Math.atan2(h.y, h.x);
                    if (angleToHouse < 0) angleToHouse += 2 * Math.PI;
                    double diff = Math.abs(angleToHouse - dirRad);
                    if (diff > Math.PI) diff = 2 * Math.PI - diff;
                    if (diff <= halfAngle) {
                        plumReach[i] = true;
                    }
                }

                // For peach and cherry trees
                for (Tree t : trees) {
                    double angleToTree = Math.atan2(t.y, t.x);
                    if (angleToTree < 0) angleToTree += 2 * Math.PI;
                    double diff = Math.abs(angleToTree - dirRad);
                    if (diff > Math.PI) diff = 2 * Math.PI - diff;
                    if (diff <= halfAngle) {
                        // This tree's scent spreads; mark houses within its fan
                        for (int i = 0; i < N; i++) {
                            House h = houses.get(i);
                            double angleToHouseFromTree = Math.atan2(h.y - t.y, h.x - t.x);
                            if (angleToHouseFromTree < 0) angleToHouseFromTree += 2 * Math.PI;
                            double diff2 = Math.abs(angleToHouseFromTree - angleToTree);
                            if (diff2 > Math.PI) diff2 = 2 * Math.PI - diff2;
                            if (diff2 <= halfAngle) {
                                if (t.type == 'P') peachReach[i] = true;
                                else cherryReach[i] = true;
                            }
                        }
                    }
                }

                // Count for each house if only plum reaches
                for (int i = 0; i < N; i++) {
                    if (plumReach[i] && !peachReach[i] && !cherryReach[i]) {
                        bestCount[i]++;
                        if (bestCount[i] > maxCount) maxCount = bestCount[i];
                    }
                }
            }

            if (maxCount == 0) {
                System.out.println("NA");
            } else {
                List<Integer> result = new ArrayList<>();
                for (int i = 0; i < N; i++) {
                    if (bestCount[i] == maxCount) result.add(houses.get(i).id);
                }
                Collections.sort(result);
                for (int id : result) {
                    System.out.println(id);
                }
            }
            System.out.println("-----");
        }
        sc.close();
    }
}

import java.io.*;
import java.util.*;

/*
 * AOJ-like geometry simulation:
 *
 * We have candidate houses, and three blossom trees:
 * - my plum tree is at the origin
 * - one peach tree
 * - one cherry tree
 *
 * For each wind record (direction, strength), each tree's scent spreads in a fan.
 * We count, for each house, on how many days ONLY my plum scent reaches it.
 * Output all house names with the maximum such count, or NA if the maximum is 0.
 *
 * Geometry model used:
 * A scent from tree T reaches point P on a day iff:
 *   - distance(T, P) <= strength
 *   - direction from T to P differs from wind direction by at most 22.5 degrees
 *
 * This is the standard interpretation of a 45-degree fan centered at the wind direction.
 *
 * Input format handled:
 * Repeated datasets:
 *   n
 *   name x y          (n lines for houses)
 *   px py             (peach tree)
 *   cx cy             (cherry tree)
 *   m
 *   dir strength      (m wind records)
 * Terminated by n = 0
 *
 * Directions accepted:
 *   N, NNE, NE, ENE, E, ESE, SE, SSE,
 *   S, SSW, SW, WSW, W, WNW, NW, NNW
 *
 * If the original judge uses exactly this common format, this solution works.
 */

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
    }

    static class House {
        String name;
        Point p;
        int count;
        House(String name, double x, double y) {
            this.name = name;
            this.p = new Point(x, y);
        }
    }

    static final double HALF_FAN = 22.5 + 1e-10;

    static final Map<String, Double> dirMap = new HashMap<>();
    static {
        // angle from +x axis counterclockwise
        dirMap.put("E", 0.0);
        dirMap.put("ENE", 22.5);
        dirMap.put("NE", 45.0);
        dirMap.put("NNE", 67.5);
        dirMap.put("N", 90.0);
        dirMap.put("NNW", 112.5);
        dirMap.put("NW", 135.0);
        dirMap.put("WNW", 157.5);
        dirMap.put("W", 180.0);
        dirMap.put("WSW", 202.5);
        dirMap.put("SW", 225.0);
        dirMap.put("SSW", 247.5);
        dirMap.put("S", 270.0);
        dirMap.put("SSE", 292.5);
        dirMap.put("SE", 315.0);
        dirMap.put("ESE", 337.5);
    }

    static double angleDeg(Point from, Point to) {
        double a = Math.toDegrees(Math.atan2(to.y - from.y, to.x - from.x));
        if (a < 0) a += 360.0;
        return a;
    }

    static double dist(Point a, Point b) {
        double dx = a.x - b.x, dy = a.y - b.y;
        return Math.hypot(dx, dy);
    }

    static double diffDeg(double a, double b) {
        double d = Math.abs(a - b);
        return Math.min(d, 360.0 - d);
    }

    static boolean reaches(Point tree, Point house, double windDir, double strength) {
        if (dist(tree, house) - strength > 1e-10) return false;
        double a = angleDeg(tree, house);
        return diffDeg(a, windDir) <= HALF_FAN;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            String first = fs.next();
            if (first == null) break;
            int n = Integer.parseInt(first);
            if (n == 0) break;

            House[] houses = new House[n];
            for (int i = 0; i < n; i++) {
                String name = fs.next();
                double x = fs.nextDouble();
                double y = fs.nextDouble();
                houses[i] = new House(name, x, y);
            }

            Point plum = new Point(0, 0);
            Point peach = new Point(fs.nextDouble(), fs.nextDouble());
            Point cherry = new Point(fs.nextDouble(), fs.nextDouble());

            int m = fs.nextInt();
            for (int day = 0; day < m; day++) {
                String dir = fs.next();
                double strength = fs.nextDouble();
                Double wd = dirMap.get(dir);
                if (wd == null) {
                    // Fallback if numeric direction is used directly
                    wd = Double.parseDouble(dir);
                }

                for (House h : houses) {
                    boolean p1 = reaches(plum, h.p, wd, strength);
                    if (!p1) continue;
                    boolean p2 = reaches(peach, h.p, wd, strength);
                    if (p2) continue;
                    boolean p3 = reaches(cherry, h.p, wd, strength);
                    if (p3) continue;
                    h.count++;
                }
            }

            int best = 0;
            for (House h : houses) best = Math.max(best, h.count);

            if (best == 0) {
                out.append("NA\n");
            } else {
                List<String> ans = new ArrayList<>();
                for (House h : houses) {
                    if (h.count == best) ans.add(h.name);
                }
                Collections.sort(ans);
                for (int i = 0; i < ans.size(); i++) {
                    if (i > 0) out.append(' ');
                    out.append(ans.get(i));
                }
                out.append('\n');
            }
        }

        System.out.print(out.toString());
    }
}
